235          int32_t chunk_elems = min(this->ub_buf_elems, inner_elems);
236          int32_t num_chunks = (inner_elems + chunk_elems - 1) / chunk_elems;
237          if(step>1){
238              DataCopyExtParams cp_in{static_cast<uint16_t>(step),static_cast<uint32_t>(inner_elems*sizeof(T)),0,0,0};
239              DataCopyExtParams cp_out{static_cast<uint16_t>(step),static_cast<uint32_t>(inner_elems*sizeof(T)),0,static_cast<uint32_t>((repeat-1)*inner_elems*sizeof(T)),0};
240              auto buf = Queue.AllocTensor<T>();
241              
242              if constexpr(sizeof(T)==1||sizeof(T)==2||sizeof(T)==4||sizeof(T)==8)
243                  DataCopyPad(buf,srcGm[in_base],cp_in,{0,0,0,0});
244              Queue.EnQue<T>(buf);
245              buf = Queue.DeQue<T>();
246              if constexpr(sizeof(T)==1||sizeof(T)==2||sizeof(T)==4||sizeof(T)==8)
247                  for(int i=0;i<repeat;i++)
248                      DataCopyPad(dstGm[out_base+i*inner_elems],buf,cp_out);
249              Queue.FreeTensor<T>(buf);
250          }else
251          for (int32_t c = 0; c < num_chunks; ++c)
252          {
253              int32_t offset = c * chunk_elems;
254              int32_t cur = min(chunk_elems, inner_elems - offset);
255              copyIn(in_base, offset, cur);
256              int32_t fill_elems = computeExpandVec(cur, inner_elems, repeat);
257              copyOut(out_base, offset, inner_elems, fill_elems, repeat, cur);
258          }
259      }
